I guess, alternatively it can be generated when setting data, should work the same, but have zero impact on starting playback, since tables are generating when loading.

```diff
diff --git a/modules/mp3/audio_stream_mp3.cpp b/modules/mp3/audio_stream_mp3.cpp
index 14a2181b26..005f716da2 100644
--- a/modules/mp3/audio_stream_mp3.cpp
+++ b/modules/mp3/audio_stream_mp3.cpp
@@ -202,14 +202,8 @@ Ref<AudioStreamPlayback> AudioStreamMP3::instantiate_playback() {

        int success = drmp3_init_memory(&mp3s->mp3d, data.ptr(), data.size(), (drmp3_allocation_callbacks *)&dr_alloc_calls);

-       if (success) { // Initialize seek table.
-               drmp3_uint32 seek_count = drmp3_get_mp3_frame_count(&mp3s->mp3d) / 20;
-               mp3s->seek_table.resize(seek_count);
-               if (drmp3_calculate_seek_points(&mp3s->mp3d, &seek_count, mp3s->seek_table.ptr())) {
-                       drmp3_bind_seek_table(&mp3s->mp3d, seek_count, mp3s->seek_table.ptr());
-               } else {
-                       mp3s->seek_table.reset(); // No point to keep it in memory.
-               }
+       if (success && !seek_table.is_empty()) {
+               drmp3_bind_seek_table(&mp3s->mp3d, seek_table.size(), seek_table.ptr());
        }

        mp3s->frames_mixed = 0;
@@ -232,6 +226,13 @@ void AudioStreamMP3::set_data(const Vector<uint8_t> &p_data) {
        sample_rate = mp3d->sampleRate;
        length = float(drmp3_get_pcm_frame_count(mp3d)) / (mp3d->sampleRate);

+       // Initialize seek table.
+       drmp3_uint32 seek_count = drmp3_get_mp3_frame_count(mp3d) / 20;
+       seek_table.resize(seek_count);
+       if (!drmp3_calculate_seek_points(mp3d, &seek_count, seek_table.ptr())) {
+               seek_table.reset();
+       }
+
        drmp3_uninit(mp3d);
        memdelete(mp3d);

diff --git a/modules/mp3/audio_stream_mp3.h b/modules/mp3/audio_stream_mp3.h
index 4fd13aaeb2..f41652f3e0 100644
--- a/modules/mp3/audio_stream_mp3.h
+++ b/modules/mp3/audio_stream_mp3.h
@@ -48,7 +48,6 @@ class AudioStreamPlaybackMP3 : public AudioStreamPlaybackResampled {
        bool looping_override = false;
        bool looping = false;
        drmp3 mp3d = {};
-       LocalVector<drmp3_seek_point> seek_table;
        uint32_t frames_mixed = 0;
        bool active = false;
        int loops = 0;
@@ -96,6 +95,7 @@ class AudioStreamMP3 : public AudioStream {
        friend class AudioStreamPlaybackMP3;

        TightLocalVector<uint8_t> data;
+       LocalVector<drmp3_seek_point> seek_table;

        float sample_rate = 1.0;
        int channels = 1;
```

